<script setup lang="ts">
import {computed,onMounted,ref,watch} from 'vue';import {useRoute} from 'vue-router';import {clone,createStudioPlace,roleLabels,familyLabels,getStudio,overnightLabels,saveStudio,type StudioPayload,type StudioPlace,type StudioRoute,type ContentStudioDocument} from './content-studio-api';import {getVisitorState,type VPayload} from './visitor-content-api';
import StudioOpeningFields from './StudioOpeningFields.vue';import StudioOpeningDisplay from './StudioOpeningDisplay.vue';import {emptyOpeningSchedule,exhibitionOpeningApplies} from '../../shared/place-opening';
import {useEditorSafety} from './editor-safety';import StudioEditorSafety from './StudioEditorSafety.vue';
import {studioMedia} from '../../shared/studio-media';const mediaItems=computed(()=>payload.value&&visitor.value?studioMedia(visitor.value.state.media,payload.value.document):[]);
import StudioPlaceActionsFields from './StudioPlaceActionsFields.vue';import {emptyNavigationDestination,emptyPlaceShareInfo} from '../../shared/place-actions';
import StudioContentCard from './StudioContentCard.vue';import './studio-tasks.css';
const task=ref('overview');
const tasks=[{id:'overview',label:'概览'},{id:'location',label:'位置与路线'},{id:'content',label:'内容编辑'},{id:'visitor',label:'游客信息'},{id:'media',label:'照片与视频'},{id:'manage',label:'核实与管理'}];
const contentCards=[{key:'summary',title:'简介',english:'English summary',purpose:'概括地点，让游客快速了解这里是什么。'},{key:'description',title:'详细介绍',english:'Description',purpose:'补充地点背景与详细介绍，保留完整段落。'},{key:'whyStop',title:'为什么值得停',english:'Why stop',purpose:'说明到访价值，帮助游客决定是否加入行程。'},{key:'firsthandNotes',title:'Jeff 实地记录',english:'Field notes',purpose:'记录真实观察与体验，区分亲见与待核实资料。'}] as const;
const visitorCards=[{key:'practicalInfo',title:'开放与实用信息',english:'Practical information',purpose:'帮助游客决定预约、门票、交通等出行安排。',lines:true},{key:'safetyNotes',title:'安全提示',english:'Safety',purpose:'记录水域、道路、天气等风险，不把未知理解为安全。'},{key:'accessNotes',title:'到达方式',english:'Getting there',purpose:'说明入口、停车与最后一段步行条件。'},{key:'seasonNotes',title:'季节提示',english:'Seasonal notes',purpose:'记录已知季节条件和限制，避免未经核实的推荐。'}] as const;
const cover=computed(()=>place.value?.photos.find(p=>p.role==='cover')||place.value?.photos[0]);
const orderedVisitorCards=computed(()=>{const c=place.value?.category||'';const first=/溪|水|瀑/.test(c)?'safetyNotes':/停车|观景|山/.test(c)?'accessNotes':'practicalInfo';return [...visitorCards].sort((a,b)=>Number(b.key===first)-Number(a.key===first));});
const focusHint=computed(()=>{const c=place.value?.category||'';return /展馆|博物|馆/.test(c)?'优先核对开放安排、预约、门票和信息来源。':/溪|水|瀑/.test(c)?'优先记录水域安全、季节条件、停车和步行入口。':/停车/.test(c)?'优先核实车辆可达性、停车说明和限制。':/观景|山/.test(c)?'优先记录到达方式、观察条件和安全提示。':'优先记录交通、路线位置和真实实地体验。';});
function chooseTask(id:string){task.value=id;tab.value='edit';}
const previewLocale=ref<'zh'|'en'>('zh');
import TencentMap from './TencentMap.vue';import {capturePosition} from './geolocation';import gcoord from 'gcoord';
import {emptyStudioPlace,studioMapPoint,type PlaceCreationContext} from '../../shared/studio-place-creation';
const props=defineProps<{creating?:boolean;basePayload?:StudioPayload;routeDraft?:StudioRoute;context?:PlaceCreationContext;initialPoint?:{latitude:number;longitude:number}}>();
const emit=defineEmits<{created:[result:{id:string;draftRevision:number;document:ContentStudioDocument}];cancel:[]}>();
const requestId=crypto.randomUUID(),contexts=ref<PlaceCreationContext[]>(props.context?[clone(props.context)]:[]),pendingFiles=ref<File[]>([]),showPicker=ref(false),manualSystem=ref('WGS84');
const route=useRoute(),payload=ref<StudioPayload|null>(null),visitor=ref<VPayload|null>(null),place=ref<StudioPlace|null>(null),message=ref(''),busy=ref(false),fieldMode=ref(false),tab=ref<'edit'|'preview'>(route.query.preview?'preview':'edit');
async function load(){[payload.value,visitor.value]=await Promise.all([props.basePayload?Promise.resolve(clone(props.basePayload)):getStudio(),getVisitorState()]);if(props.routeDraft){const index=payload.value.document.routes.findIndex(r=>r.id===props.routeDraft!.id);payload.value.document.routes[index]=clone(props.routeDraft);}place.value=props.creating?emptyStudioPlace():clone(payload.value.document.places[String(route.params.code)]);place.value.openingSchedule??=emptyOpeningSchedule();place.value.navigationDestination??=emptyNavigationDestination();place.value.shareInfo??=emptyPlaceShareInfo();manualSystem.value=place.value.coordinates.system;if(props.creating&&props.initialPoint)setPoint(props.initialPoint);safety.capture();}onMounted(load);
const themes=computed(()=>payload.value?.document.themes.filter(t=>!t.archivedAt)||[]);const routes=computed(()=>payload.value?.document.routes.filter(r=>r.memberships.some(m=>m.placeId===place.value?.id))||[]);
function today(){if(place.value)place.value.trust.lastCheckedAt=new Date().toISOString().slice(0,10);}
const safety=useEditorSafety({payload,current:()=>props.creating?{place:place.value,contexts:contexts.value}:place.value,setCurrent:v=>{if(props.creating){place.value=v.place;contexts.value=v.contexts;}else place.value=v;},select:doc=>{const p=doc.places[place.value!.id]?clone(doc.places[place.value!.id]):undefined;if(p){p.openingSchedule??=emptyOpeningSchedule();p.navigationDestination??=emptyNavigationDestination();p.shareInfo??=emptyPlaceShareInfo();}return p;},save:()=>save(),extraDirty:()=>pendingFiles.value.length>0,busy:()=>busy.value,creation:props.creating,validateLatest:next=>props.routeDraft&&JSON.stringify(props.basePayload?.document.routes.find(r=>r.id===props.routeDraft!.id))!==JSON.stringify(next.document.routes.find(r=>r.id===props.routeDraft!.id))?'当前路线也被其他窗口修改，不能用旧路线覆盖。地点输入仍保留；请查看差异并继续编辑，或先处理路线修改。':null});
const editableCategory=computed({get:()=>place.value?.category||'',set:next=>{if(!place.value)return;const before=place.value.category;place.value.category=next;if(exhibitionOpeningApplies({category:next})&&!exhibitionOpeningApplies({category:before})&&place.value.openingSchedule)place.value.openingSchedule.confirmed=false;}});
watch(()=>route.params.code,()=>{if(!props.creating)void load();});
const latitudeError=computed(()=>place.value&&(!Number.isFinite(place.value.coordinates.latitude)||Math.abs(place.value.coordinates.latitude)>90)?'纬度必须在 -90 至 90 之间':''),longitudeError=computed(()=>place.value&&(!Number.isFinite(place.value.coordinates.longitude)||Math.abs(place.value.coordinates.longitude)>180)?'经度必须在 -180 至 180 之间':'');
const pickerPoint=computed(()=>place.value&&!place.value.coordinateMissing?studioMapPoint(place.value.coordinates):null);
function setPoint(point:{latitude:number;longitude:number},system='GCJ-02'){if(!place.value)return;const [longitude,latitude]=gcoord.transform([point.longitude,point.latitude],system==='WGS84'?gcoord.WGS84:gcoord.GCJ02,gcoord.WGS84);place.value.coordinates={latitude,longitude,system:'WGS84'};place.value.coordinateMissing=false;manualSystem.value='WGS84';}
async function locate(){try{const position=await capturePosition();setPoint({latitude:position.coords.latitude,longitude:position.coords.longitude},'WGS84');message.value='当前位置已保存为 WGS84，腾讯地图显示时转换为 GCJ-02，请核对。';}catch(e){message.value=(e as Error).message;}}
function convertManual(){if(!place.value)return;const c=place.value.coordinates;if(!Number.isFinite(c.latitude)||!Number.isFinite(c.longitude)||Math.abs(c.latitude)>90||Math.abs(c.longitude)>180){message.value=[latitudeError.value,longitudeError.value].filter(Boolean).join('；');return;}setPoint(c,manualSystem.value);message.value='已确认 WGS84 地图坐标';}
function addAssociation(){const r=payload.value?.document.routes.find(r=>!r.archivedAt&&!contexts.value.some(c=>c.routeId===r.id)),s=r?.stages.find(s=>!s.archivedAt);if(r&&s)contexts.value.push({routeId:r.id,stageId:s.id,groupId:null,role:'secondary-stop',order:100});}
function changeRoute(c:PlaceCreationContext){const r=payload.value?.document.routes.find(r=>r.id===c.routeId);c.stageId=r?.stages.find(s=>!s.archivedAt)?.id||'';c.groupId=null;}
function associationStages(c:PlaceCreationContext){return payload.value?.document.routes.find(r=>r.id===c.routeId)?.stages.filter(s=>!s.archivedAt)||[];}
function associationGroups(c:PlaceCreationContext){return associationStages(c).find(s=>s.id===c.stageId)?.groups.filter(g=>!g.archivedAt)||[];}
async function uploadPending(){if(!visitor.value)return;for(const file of [...pendingFiles.value]){const slot=`content.library-${crypto.randomUUID()}.asset`,response=await fetch(`/api/admin/visitor-content/visual-media/${encodeURIComponent(slot)}`,{method:'POST',body:file,headers:{'Content-Type':file.type,'X-Media-Version':String(visitor.value.state.media.version),'X-Original-Name':encodeURIComponent(file.name)}}),result=await response.json();if(!response.ok)throw Error(result.error);visitor.value=await getVisitorState();const image=visitor.value.state.media.items[slot];addPhoto(image.fileName);pendingFiles.value.splice(pendingFiles.value.indexOf(file),1);}}
async function save(summary='修改地点资料'){if(!payload.value||!place.value||busy.value)return false;if(latitudeError.value||longitudeError.value){message.value=[latitudeError.value,longitudeError.value].filter(Boolean).join('；');return false;}if(!place.value.name.zh.trim()){message.value='请填写中文名称';return false;}busy.value=true;try{await uploadPending();const doc=clone(payload.value.document);if(props.routeDraft){const index=doc.routes.findIndex(r=>r.id===props.routeDraft!.id);doc.routes[index]=clone(props.routeDraft);}
 if(props.creating){const result=await createStudioPlace(payload.value,doc,clone(place.value),clone(contexts.value),requestId);safety.capture();emit('created',result);return true;}
 doc.places[place.value.id]=clone(place.value);const result=await saveStudio(payload.value,doc,'place',place.value.id,`${summary}：${place.value.name.zh}`);message.value=`草稿已保存（版本 ${result.draftRevision}），公开网站尚未改变。`;payload.value.document=doc;payload.value.draftRevision=result.draftRevision;safety.capture(doc.places[place.value.id]);return true;
 }catch(e){safety.fail(e);message.value='';return false;}finally{busy.value=false;}}
async function archive(){if(!place.value)return;place.value.archivedAt=place.value.archivedAt?null:new Date().toISOString();if(place.value.archivedAt){place.value.archivePublished=place.value.published;place.value.published=false;}else place.value.published=place.value.archivePublished||false;await save(place.value.archivedAt?'归档地点':'恢复地点');}
function addLink(kind:'videos'|'storyLinks'|'researchLinks'){if(!place.value)return;place.value[kind].push({id:crypto.randomUUID(),title:{zh:'',en:''},url:'',...(kind==='videos'?{platform:'douyin' as const}: {})});}
function addPhoto(fileName:string){if(!place.value||place.value.photos.some(photo=>photo.fileName===fileName))return;place.value.photos.push({id:crypto.randomUUID(),fileName,alt:{zh:`${place.value.name.zh}现场照片`,en:''},role:place.value.photos.length?'gallery':'cover',order:place.value.photos.length*10});}
</script><template>
<div v-if="payload&&place" class="workspace-page studio-page place-studio task-editor">
 <div class="workspace-title"><div><button v-if="creating" class="quiet" :disabled="busy" @click="safety.requestLeave(()=>emit('cancel'))">取消新建 · 返回原位置</button><RouterLink v-else to="/studio/places">← 返回地点</RouterLink><p class="kicker">{{creating?'编号将在保存时自动分配':place.id}}</p><h1>{{creating?'新建地点':place.name.zh}}</h1></div><p class="save-state" role="status">{{busy?'正在保存…':safety.dirty.value?'未保存修改':'当前输入已保存 / 尚未修改'}}<br>只保存本地草稿</p></div>
 <StudioEditorSafety :state="safety"/><p v-if="message" class="inline-message">{{message}}</p>
 <div class="task-layout"><nav class="task-navigation" aria-label="地点任务栏目"><button v-for="item in tasks" :key="item.id" :class="{active:task===item.id&&tab==='edit'}" :aria-current="task===item.id&&tab==='edit'?'page':undefined" @click="chooseTask(item.id)">{{item.label}}</button><button v-if="tab==='preview'" @click="tab='edit'">返回编辑</button></nav>
 <div class="task-main">
 <div v-show="tab==='edit'">
 <section v-show="task==='overview'" class="task-panel" aria-label="概览"><h2>概览</h2><div class="overview-top"><div class="overview-cover"><img v-if="cover" :src="`/api/admin/visitor-content/media/${cover.fileName}`" :alt="cover.alt.zh"><span v-else>尚未添加封面</span></div><div><p>{{creating?'新地点草稿':place.id}} · {{place.category||'地点类型待填写'}}</p><p>{{payload.publishedPlaceIds?.includes(place.id)?'已有公开版本':'尚未公开'}} · {{place.published?'草稿设置为公开显示':'草稿设置为未公开'}}</p><p>{{safety.dirty.value?'当前有未保存输入':'本地草稿版本 '+payload.draftRevision}}，保存不会发布到公网。</p></div></div><div class="form-grid"><label>中文名称（必填）<input v-model="place.name.zh" required></label><label>地点类型<input v-model="editableCategory" list="place-categories"><datalist id="place-categories"><option v-for="category in [...new Set(Object.values(payload.document.places).map(p=>p.category))]" :value="category"/></datalist></label><label class="inline-check"><input v-model="place.published" type="checkbox">公开显示（草稿设置）</label><label class="inline-check"><input v-model="place.recommended" type="checkbox">推荐显示</label></div>
 <StudioOpeningFields :place="place"/><div class="overview-status"><button @click="chooseTask('location')">地图位置：{{place.coordinateMissing?'待选点':'已设置'}} →</button><button @click="chooseTask('media')">照片：{{place.photos.length?'已关联 '+place.photos.length+' 张':'尚未添加'}} →</button><button @click="chooseTask('content')">简介：{{place.summary.zh.trim()?'已填写':'待完善'}} →</button><button @click="chooseTask('content')">英文名称：{{place.name.en.trim()?'已填写（核实状态见管理）':'待填写'}} →</button><button @click="chooseTask('manage')">实地核验：{{place.trust.checkedInPerson?'已主动标记':'尚未确认'}} →</button></div><h3>路线归属</h3><p v-if="!routes.length&&!contexts.length">尚未关联路线，可到“位置与路线”设置。</p><p v-for="r in routes">{{r.name.zh}}<span v-for="m in r.memberships.filter(m=>m.placeId===place!.id)"> → {{r.stages.find(s=>s.id===m.stageId)?.title.zh||'阶段未找到'}} → {{m.groupId?r.stages.find(s=>s.id===m.stageId)?.groups.find(g=>g.id===m.groupId)?.title.zh||'分组未找到':'未分组'}}</span></p><p v-if="creating&&contexts.length">当前创建上下文已关联 {{contexts.length}} 条路线，保存时一起建立关联。</p><p class="task-purpose">已填写不等于已核实。英文、照片和详细介绍可后补。</p></section>
 <section v-show="task==='location'" class="task-panel" aria-label="位置与路线"><h2>位置与路线</h2><section class="studio-coordinate-fields"><h3>地图位置</h3><p>{{place.coordinateMissing?'尚未选点，可以先保存草稿':'WGS84 坐标已设置'}}。腾讯地图显示与点选使用 GCJ-02。</p><div class="field-actions"><button @click="showPicker=!showPicker">点击地图选择位置</button><button @click="locate">使用当前位置</button></div><TencentMap v-if="showPicker" pick :selected="pickerPoint" :center="pickerPoint" @pick="setPoint($event)"/><details><summary>手动坐标与坐标系</summary><div class="form-grid"><label>纬度<input v-model.number="place.coordinates.latitude" type="number" step="any" @input="place.coordinateMissing=true"><small v-if="latitudeError" class="field-error" role="alert">{{latitudeError}}</small></label><label>经度<input v-model.number="place.coordinates.longitude" type="number" step="any" @input="place.coordinateMissing=true"><small v-if="longitudeError" class="field-error" role="alert">{{longitudeError}}</small></label><label>输入坐标系<select v-model="manualSystem"><option>GCJ-02</option><option>WGS84</option></select></label></div><button @click="convertManual">确认手动坐标</button></details></section><StudioPlaceActionsFields :place="place"/>
 <div class="form-grid"><label>所属区域<input v-model="place.region.zh"></label><label>Region（English）<input v-model="place.region.en"></label><label>地址<input v-model="place.address.zh"></label><label>Address（English）<input v-model="place.address.en"></label></div><h3>路线与分类</h3><div v-for="r in routes" :key="r.id"><div v-for="m in r.memberships.filter(m=>m.placeId===place!.id)" :key="m.stageId+'|'+m.groupId" class="place-route-association"><p>{{r.name.zh}} → {{r.stages.find(s=>s.id===m.stageId)?.title.zh||'阶段未找到'}} → {{m.groupId?r.stages.find(s=>s.id===m.stageId)?.groups.find(g=>g.id===m.groupId)?.title.zh||'分组未找到':'未分组'}}{{m.visible?'':'（已隐藏）'}}</p><RouterLink :to="{path:'/studio/routes/'+r.id,query:{stage:m.stageId,group:m.groupId||'',place:place.id}}">查看路线中的位置</RouterLink></div></div><p v-if="!creating">路线关系在对应路线管理中编辑；离开前会保护当前未保存输入。</p>
 <div v-if="creating"><div v-for="(c,index) in contexts" class="form-grid creation-association"><label>Route<select aria-label="Route" v-model="c.routeId" @change="changeRoute(c)"><option v-for="r in payload.document.routes.filter(r=>!r.archivedAt&&!contexts.some((other,i)=>i!==index&&other.routeId===r.id))" :value="r.id">{{r.name.zh}}</option></select></label><label>Stage<select aria-label="Stage" v-model="c.stageId" @change="c.groupId=null"><option v-for="s in associationStages(c)" :value="s.id">{{s.title.zh}}</option></select></label><label>Group<select aria-label="Group" v-model="c.groupId"><option :value="null">未分组</option><option v-for="g in associationGroups(c)" :value="g.id">{{g.title.zh}}</option></select></label><label>地点角色<select v-model="c.role"><option v-for="(label,key) in roleLabels" :value="key">{{label}}</option></select></label><label>显示顺序<input v-model.number="c.order" type="number"></label><button @click="contexts.splice(index,1)">移除这条关联</button></div><button @click="addAssociation">＋ 关联路线</button></div><h3>兴趣主题</h3><div class="theme-checks"><label v-for="theme in themes"><input v-model="place.themeIds" type="checkbox" :value="theme.id">{{theme.name.zh}}</label></div></section>
 <section v-show="task==='content'" class="task-panel" aria-label="内容编辑"><h2>内容编辑</h2><label>英文名称<input v-model="place.name.en" placeholder="可后补，不自动机器翻译"></label><StudioContentCard v-for="card in contentCards" :key="card.key" :title="card.title" :purpose="card.purpose" :english-label="card.english" :value="place[card.key]"/><article class="task-content-card"><h3>故事与研究</h3><p>使用真实资料链接补充历史、自然与人文知识。</p><div v-for="kind in (['storyLinks','researchLinks'] as const)"><h4>{{kind==='storyLinks'?'故事':'研究资料'}}</h4><div v-for="item in place[kind]" :key="item.id" class="link-editor"><input v-model="item.title.zh" aria-label="资料标题（中文）" placeholder="标题"><input v-model="item.title.en" aria-label="资料标题（英文）" placeholder="English title"><input v-model="item.url" aria-label="资料链接" placeholder="https://"><button @click="place[kind].splice(place[kind].indexOf(item),1)">移除关联</button></div><button @click="addLink(kind)">{{kind==='storyLinks'?'＋ 故事':'＋ 研究资料'}}</button></div></article></section>
 <section v-show="task==='visitor'" class="task-panel" aria-label="游客信息"><h2>游客信息</h2><p class="task-focus">{{focusHint}} 所有类型均可编辑下面的其他信息；切换类型不会删除内容。</p>
 <StudioContentCard v-for="card in orderedVisitorCards" :key="card.key" :title="card.title" :purpose="card.purpose" :english-label="card.english" :value="place[card.key]" :lines="card.key==='practicalInfo'"/>
 <details><summary>出行信息</summary><div class="facility-grid"><label><input v-model="place.facilities.parking" type="checkbox">停车</label><label><input v-model="place.facilities.toilet" type="checkbox">卫生间</label><label><input v-model="place.facilities.food" type="checkbox">餐饮</label><label><input v-model="place.facilities.shop" type="checkbox">商店</label><label><input v-model="place.facilities.lodging" type="checkbox">住宿</label></div><StudioContentCard v-for="field in ([['parking','停车说明','Parking'],['toiletNote','卫生间位置','Restrooms'],['foodNote','餐饮说明','Food'],['shopNote','商店说明','Shops'],['lodgingNote','住宿说明','Lodging']] as const)" :title="field[1]" purpose="只填写已有依据的设施信息。" :english-label="field[2]" :value="place[field[0]]"/></details>
 <details><summary>亲子</summary><div class="choice-grid"><label v-for="(label,key) in familyLabels"><input v-model="place.familySuitability" type="radio" :value="key">{{label}}</label></div><StudioContentCard title="亲子说明" english-label="Family notes" purpose="区分适合、有条件适合、不适合和未知。" :value="place.familyNotes"/></details><details><summary>床车过夜</summary><div class="choice-grid overnight"><label v-for="(label,key) in overnightLabels"><input v-model="place.overnightStatus" type="radio" :value="key">{{label}}</label></div><StudioContentCard title="过夜补充说明" english-label="Overnight notes" purpose="曾经住过不等于当前允许；保留核实来源。" :value="place.overnightNotes"/><div class="form-grid"><label>最后确认日期<input v-model="place.overnightLastCheckedAt" type="date"></label><label>来源<input v-model="place.overnightSource"></label></div></details></section>
 <section v-show="task==='media'" class="task-panel" aria-label="照片与视频"><h2>照片与视频</h2><details open><summary>照片</summary><p v-if="!place.photos.length">尚未设置封面。可以从媒体库选择，或先上传新照片。</p><div v-for="(photo,index) in place.photos" :key="photo.id" class="media-row"><img :src="`/api/admin/visitor-content/media/${photo.fileName}`" :alt="photo.alt.zh"><div><p class="media-file-name">{{photo.fileName}}</p><label>中文图片说明<input v-model="photo.alt.zh"></label><label>English image description<input v-model="photo.alt.en"></label></div><label>图片用途<select v-model="photo.role"><option value="cover">封面（同时用于分享）</option><option value="gallery">图集</option></select></label><label>照片顺序<input v-model.number="photo.order" type="number"></label><button class="remove-button" @click="place.photos.splice(index,1)">移除关联</button></div><div class="field-actions"><label class="button quiet">从相册上传<input type="file" multiple accept="image/jpeg,image/png,image/webp" @change="pendingFiles.push(...Array.from(($event.target as HTMLInputElement).files||[]))"></label><label class="button quiet">拍照<input type="file" accept="image/jpeg,image/png,image/webp" capture="environment" @change="pendingFiles.push(...Array.from(($event.target as HTMLInputElement).files||[]))"></label></div><p v-for="(f,i) in pendingFiles" class="media-file-name">待保存图片：{{f.name}} <button @click="pendingFiles.splice(i,1)">移除</button></p><h3>复用媒体库</h3><div class="media-library-grid compact"><button v-for="item in mediaItems" :key="item.image.id" type="button" @click="addPhoto(item.image.fileName)"><img :src="`/api/admin/visitor-content/media/${item.image.fileName}`"><span>{{item.title}}</span><small>被 {{item.places.length}} 个地点使用（当前草稿）</small><small>{{item.places.map(p=>p.name).join('、')||'当前草稿没有地点引用'}}</small><small>{{place.photos.some(p=>p.fileName===item.image.fileName)?'本地点已关联':'点击关联此照片'}}</small></button></div><p>移除关联不删除媒体文件或历史引用。封面优先用于地点及分享预览。</p></details><details><summary>视频</summary><div v-for="video in place.videos" :key="video.id" class="link-editor"><select v-model="video.platform"><option>douyin</option><option>youtube</option><option>instagram</option><option>tiktok</option></select><input v-model="video.title.zh" placeholder="标题"><input v-model="video.title.en" placeholder="English title"><input v-model="video.url" placeholder="https://"><button @click="place.videos.splice(place.videos.indexOf(video),1)">移除关联</button></div><button @click="addLink('videos')">＋ 关联视频</button></details></section>
 <section v-show="task==='manage'" class="task-panel" aria-label="核实与管理"><h2>核实与管理</h2><h3>实地核验</h3><div class="trust-grid"><label><input v-model="place.trust.firsthand" type="checkbox">我亲自到过</label><label><input v-model="place.trust.checkedInPerson" type="checkbox">我亲自核验过信息</label><label><input v-model="place.trust.officialSource" type="checkbox">有官方资料</label><label><input v-model="place.trust.recheckBeforeGoing" type="checkbox">出发前需要重新确认</label></div><label>最近核验日期<input v-model="place.trust.lastCheckedAt" type="date"></label><button @click="today">最近核验设为今天</button><p>设置日期或保存不会自动确认资料真实有效。</p><details><summary>高级地图与名称设置</summary><div class="form-grid"><label>中文简称<input v-model="place.shortName.zh"></label><label>英文简称<input v-model="place.shortName.en"></label><label>拼音<input v-model="place.pinyin"></label><label>英文名称状态<select v-model="place.englishNameStatus"><option value="pending">待人工核验</option><option value="pinyin">拼音</option><option value="translated">人工翻译</option><option value="established">通行英文名</option><option value="official">官方英文名</option></select></label><label>地图标签优先级<select v-model.number="place.labelPriority"><option :value="100">100 · 路线骨架</option><option :value="80">80 · 重要地点</option><option :value="60">60 · 一般停留</option><option :value="40">40 · 补给/支线</option><option :value="20">20 · 次级服务</option></select></label></div><div class="map-label-preview"><b>{{place.shortName.zh||place.name.zh}}</b><strong>{{place.name.zh}}</strong></div></details><div class="field-actions"><RouterLink to="/studio/history">修改历史</RouterLink><RouterLink to="/studio/history">备份与恢复</RouterLink><button v-if="!creating" class="quiet" :disabled="busy" @click="archive">{{place.archivedAt?'恢复地点':'归档地点'}}</button></div></section>
 </div>
 <div v-if="tab==='preview'" class="place-live-preview"><label>预览语言<select v-model="previewLocale"><option value="zh">中文</option><option value="en">English</option></select></label><div class="studio-place-cover large"><img v-if="cover" :src="`/api/admin/visitor-content/media/${cover.fileName}`" :alt="cover.alt[previewLocale]"><span v-else>地</span></div><article><small>{{place.region[previewLocale]}}</small><h2>{{place.name[previewLocale]||place.name.zh}}</h2><p v-if="previewLocale==='en'&&!place.name.en">English name not added yet.</p><StudioOpeningDisplay :place="place" :locale="previewLocale" details/><StudioPlaceActionsFields :place="place" preview :locale="previewLocale"/><div class="visual-card-tags"><span v-for="id in place.themeIds">{{themes.find(t=>t.id===id)?.name[previewLocale]}}</span></div><section v-for="card in [...contentCards,...visitorCards]" :key="card.key"><h3>{{previewLocale==='zh'?card.title:card.english}}</h3><p class="preview-note">{{Array.isArray(place[card.key][previewLocale])?(place[card.key][previewLocale] as string[]).join('\n'):place[card.key][previewLocale]|| (previewLocale==='zh'?'尚未填写':'English not added yet.')}}</p></section><section v-for="field in ([['parking','停车说明','Parking'],['familyNotes','亲子说明','Family information'],['overnightNotes','过夜说明','Overnight stays']] as const)"><h3>{{previewLocale==='zh'?field[1]:field[2]}}</h3><p>{{place[field[0]][previewLocale]}}</p></section><p>{{previewLocale==='zh'?'最近核验':'Last checked'}}：{{place.trust.lastCheckedAt||(previewLocale==='zh'?'未填写':'Not recorded')}}</p></article></div>
 </div></div>
 <div class="editor-action-bar task-save-bar"><span>{{busy?'正在保存…':safety.dirty.value?'未保存修改':'本地草稿'}} · 保存不会发布</span><button v-if="creating" :disabled="busy" @click="safety.requestLeave(()=>emit('cancel'))">取消</button><button @click="tab=tab==='preview'?'edit':'preview'">{{tab==='preview'?'返回编辑':'预览本地草稿'}}</button><button class="primary-action" :disabled="busy" @click="save()">保存地点草稿</button></div>
</div>
</template>
